window.ScripturaLexicons.BDAG_PART_0042 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apo-bdag\" data-source=\"BDAG\" data-search=\"ἀπό apó apo de; desde; a partir de; para longe de; por causa de; por intermédio de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπό</td><td>Preposição com genitivo</td><td>de; desde; a partir de; para longe de; por causa de; por intermédio de</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apobaino-bdag\" data-source=\"BDAG\" data-search=\"ἀποβαίνω apobaínō apobaino desembarcar; sair; resultar em; levar a BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀποβαίνω</td><td>Verbo</td><td>desembarcar; sair; resultar em; levar a</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apoballo-bdag\" data-source=\"BDAG\" data-search=\"ἀποβάλλω apobállō apoballo tirar; despir; rejeitar; perder; depor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀποβάλλω</td><td>Verbo</td><td>tirar; despir; rejeitar; perder; depor</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apoblepo-bdag\" data-source=\"BDAG\" data-search=\"ἀποβλέπω apoblépō apoblepo olhar para; atentar para; prestar atenção BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀποβλέπω</td><td>Verbo</td><td>olhar para; atentar para; prestar atenção</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apobletos-bdag\" data-source=\"BDAG\" data-search=\"ἀπόβλητος apóblētos apobletos rejeitado; impuro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπόβλητος</td><td>Adjetivo</td><td>rejeitado; impuro</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apobole-bdag\" data-source=\"BDAG\" data-search=\"ἀποβολή apobolḗ apobole rejeição; perda BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀποβολή</td><td>Substantivo feminino</td><td>rejeição; perda</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apoginomai-bdag\" data-source=\"BDAG\" data-search=\"ἀπογίνομαι apogínomai apoginomai morrer; falecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπογίνομαι</td><td>Verbo</td><td>morrer; falecer</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apoginosko-bdag\" data-source=\"BDAG\" data-search=\"ἀπογινώσκω apoginṓskō apoginosko desistir de; perder a esperança; desesperar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπογινώσκω</td><td>Verbo</td><td>desistir de; perder a esperança; desesperar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apognorizo-bdag\" data-source=\"BDAG\" data-search=\"ἀπογνωρίζω apognōrízō apognorizo desapossar; rejeitar; privar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπογνωρίζω</td><td>Verbo</td><td>desapossar; rejeitar; privar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apographe-bdag\" data-source=\"BDAG\" data-search=\"ἀπογραφή apographḗ apographe lista; inventário; recenseamento; registro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπογραφή</td><td>Substantivo feminino</td><td>lista; inventário; recenseamento; registro</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apographo-bdag\" data-source=\"BDAG\" data-search=\"ἀπογράφω apográphō apographo copiar; registrar; inscrever; recensear BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπογράφω</td><td>Verbo</td><td>copiar; registrar; inscrever; recensear</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apodeiknumi-bdag\" data-source=\"BDAG\" data-search=\"ἀποδείκνυμι apodeíknumi apodeiknumi mostrar; proclamar; designar; demonstrar; provar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀποδείκνυμι</td><td>Verbo</td><td>mostrar; proclamar; designar; demonstrar; provar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apodeixis-bdag\" data-source=\"BDAG\" data-search=\"ἀπόδειξις apódeixis apodeixis demonstração; prova BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπόδειξις</td><td>Substantivo feminino</td><td>demonstração; prova</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-apo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apó⟧</span><span class=\"separator\">·</span><span>preposição com genitivo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Preposição com genitivo (Homero e outros); veja a literatura em <span class=\"greek\">ἀνά</span>, início, e KDieterich, <em>IndogF</em> 24 (1909) 93–158; LfgrE s.v. O sentido básico é <strong>separação de alguém ou alguma coisa</strong>, do qual se desenvolveram os demais. No NT, invadiu o domínio de <span class=\"greek\">ἐκ</span>, <span class=\"greek\">ὑπό</span>, <span class=\"greek\">παρά</span> e do genitivo de separação próprios do ático; veja Mlt. 102, 246; Mlt-Turner 258s.</p>\n<p class=\"entry-text\"><b>1.</b> <strong>Indicador de separação de um lugar, pessoa ou coisa; de, para longe de.</strong> <b>a.</b> Com todos os verbos que designam movimento, especialmente os compostos com <span class=\"greek\">ἀπό</span>: <span class=\"greek\">ἀπάγεσθαι, ἀπαλλάσσεσθαι, ἀπελαύνειν, ἀπέρχεσθαι, ἀπολύεσθαι, ἀποπλανᾶσθαι, ἀποστέλλειν, ἀποφεύγειν, ἀποχωρεῖν, ἀποχωρίζεσθαι</span>; mas também com <span class=\"greek\">ἀνίστασθαι, διαστῆναι, διέρχεσθαι, ἐκδημεῖν, ἐκκινεῖν, ἐκπλεῖν, ἐκπορεύεσθαι, ἐξέρχεσθαι, ἐξωθεῖν, ἐπιδιδόναι, μεταβαίνειν, μετατίθεσθαι, νοσφίζειν, παραγίνεσθαι, πλανᾶσθαι, πορεύεσθαι, ὑπάγειν, ὑποστρέφειν, φεύγειν</span>; consulte os verbetes respectivos.</p>\n<p class=\"entry-text\"><b>b.</b> Com verbos que exprimem separação: <span class=\"greek\">ἐκβάλλειν τὸ κάρφος ἀπὸ τοῦ ὀφθαλμοῦ</span>, <strong>tirar o argueiro do olho</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7.4</a>, variante textual por <span class=\"greek\">ἐκ</span>. <span class=\"greek\">ἐξέβαλον ἀπὸ τῆς πήρας αὐτῶν δῶρα</span>, <strong>tiraram presentes de suas bolsas de viagem</strong>, GJs 21.3. <span class=\"greek\">ἀπολύεσθαι ἀπὸ ἀνδρός</span>, <strong>divorciar-se do marido</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16.18</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.33</a>. Também com <span class=\"greek\">ἀποκυλίειν, ἀπολαμβάνεσθαι, ἀποστρέφειν, ἐπιστρέφεσθαι, ἐπανάγειν, αἴρειν, ἀφαιρεῖν, ἀπολέσθαι, μερίζειν</span> e outros (veja os verbetes). <span class=\"greek\">κενὸς ἀπό τινος</span>, <strong>vazio de algo</strong>, Hs 9.19.2; <span class=\"greek\">ἔρημος ἀπό τινος</span>, <strong>desprovido de algo</strong> (Jr 51.2), 2Cl 2.3.</p>\n<p class=\"entry-text\">Com verbos que exprimem separação em sentido mais amplo, como <strong>soltar, libertar, absolver</strong>: <span class=\"greek\">ἀπορφανίζειν, ἀποσπᾶν, διεγείρεσθαι, δικαιοῦν, ἐκδικοῦν, ἐλευθεροῦν, λούειν, λύειν, λυτροῦν, ῥαντίζειν, σαλεύειν, στέλλειν, σῴζειν, φθείρειν</span>; veja os verbetes; daí também <span class=\"greek\">ἀθῷος</span> (Sus 46, Teodócio, variante) em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.24</a>; <span class=\"greek\">καθαρὸς ἀπό τινος</span> (Tb 3.14; mas veja Dssm. NB 24 [BS 196, 216]) em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 20.26</a>; compare Kuhring 54.</p>\n<p class=\"entry-text\"><b>c.</b> Verbos referentes a <strong>precaver-se, envergonhar-se</strong> e semelhantes empregam <span class=\"greek\">ἀπό</span> para indicar a ocasião ou o objeto da cautela, da vergonha ou do medo; assim <span class=\"greek\">αἰσχύνεσθαι, βλέπειν, μετανοεῖν, προσέχειν, φοβεῖσθαι, φυλάσσειν, φυλάσσεσθαι</span>; veja adiante 5.</p>\n<p class=\"entry-text\"><b>d.</b> Com verbos de <strong>ocultar, esconder, impedir</strong>, a pessoa de quem algo é ocultado aparece com <span class=\"greek\">ἀπό</span>: <span class=\"greek\">κρύπτειν τι ἀπό τινος, παρακαλύπτειν τι ἀπό τινος, κωλύειν τι ἀπό τινος</span>; veja seus verbetes.</p>\n<p class=\"entry-text\"><b>e.</b> Em construções de sentido condensado: <span class=\"greek\">ἀνάθεμα εἶναι ἀπὸ τοῦ Χριστοῦ</span>, <strong>estar separado de Cristo por uma maldição</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9.3</a>. <span class=\"greek\">μετανοεῖν ἀπὸ τῆς κακίας</span>, <strong>arrepender-se da maldade</strong> (Jr 8.6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 8.22</a>. <span class=\"greek\">ἀποθνῄσκειν ἀπό τινος</span>, <strong>ficar livre de algo por meio da morte</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2.20</a>. <span class=\"greek\">φθείρεσθαι ἀπὸ τῆς ἁπλότητος</span>, <strong>ser desviado ruinosamente do compromisso de todo o coração</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11.3</a>; compare Hs 6.2.4.</p>\n<p class=\"entry-text\"><b>f.</b> <strong>Substitui o genitivo partitivo</strong> (Heródoto 6.27.2; Tucídides 7.87.6; PPetr III, 11, 20; PIand 8, 6; Kuhring 20; Rossberg 22; Johannessohn, <em>Präp.</em> 17): <span class=\"greek\">τίνα ἀπὸ τῶν δύο;</span>, <strong>qual dos dois?</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.21</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.38</a>; 19.39; PTebt 299, 13; 1Mc 1.13; 3.24; Sir 6.6; 46.8. <span class=\"greek\">τὰ ἀπὸ τοῦ πλοίου</span>, <strong>pedaços do navio</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.44\" target=\"_blank\" rel=\"noopener noreferrer\">At 27.44</a>. <span class=\"greek\">ἐκχεῶ ἀπὸ τοῦ πνεύματός μου</span>, <strong>derramarei do meu Espírito</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.17</a>s. (Jl 3.1s.). <span class=\"greek\">λαμβάνειν ἀπὸ τῶν καρπῶν</span>, <strong>receber uma parte da colheita de uvas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.2</a>; compare Justino, <em>A I</em> 65.5, <span class=\"greek\">μεταλαβεῖν ἀπὸ τοῦ … ἄρτου</span>, <strong>participar de parte do pão</strong>.</p>\n<p class=\"entry-text\">De alimentos (Dn 1.13; 4.33a; 2Mc 7.1): <span class=\"greek\">ἐσθίειν ἀπὸ τῶν ψιχίων</span>, <strong>comer algumas migalhas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15.27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7.28</a>; <span class=\"greek\">χορτάζεσθαι ἀπό τινος</span>, <strong>fartar-se de algo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16.21</a>; <span class=\"greek\">αἴρειν ἀπὸ τῶν ἰχθύων</span>, <strong>recolher o que sobrou dos peixes</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.43</a>; <span class=\"greek\">ἐνέγκατε ἀπὸ τῶν ὀψαρίων</span>, <strong>trazei alguns peixes</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21.10</a> — único exemplo desse uso em João (M.-É. Boismard, <em>Le chapitre 21 de Saint Jean</em>, <em>RB</em> 54 [1947] 492). De bebida (Sir 26.12): <span class=\"greek\">πίνειν ἀπὸ τοῦ γενήματος τῆς ἀμπέλου</span>, <strong>beber do produto da videira</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.18</a>.</p>\n<p class=\"entry-text\"><b>2.</b> <strong>Assinala o ponto de onde algo começa</strong>, literal ou figuradamente. <b>a.</b> De lugar: <strong>de, a partir de</strong> (Justino, <em>D.</em> 86.1, <span class=\"greek\">ἀπὸ τῆς πέτρας ὕδωρ ἀναβλύσαν</span>, <strong>água brotando da rocha</strong>). <span class=\"greek\">σημεῖον ἀπὸ τοῦ οὐρανοῦ</span>, <strong>sinal do céu</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.11</a>; <span class=\"greek\">ἀπὸ πόλεως εἰς πόλιν</span>, <strong>de cidade em cidade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23.34</a>; <span class=\"greek\">ἀπ’ ἄκρων οὐρανῶν ἕως ἄκρων αὐτῶν</span>, <strong>de uma extremidade do céu à outra</strong> (Dt 30.4; Sl 18.7), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13.27</a>. <span class=\"greek\">ἀπ’ ἄνωθεν ἕως κάτω</span>, <strong>de alto a baixo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.51</a>; <span class=\"greek\">ἀρξάμενοι ἀπὸ Ἰερουσαλήμ</span>, <strong>começando por Jerusalém</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.47</a> (também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 1.22</a>; 10.37); <span class=\"greek\">ἀφ’ ὑμῶν ἐξήχηται ὁ λόγος τοῦ κυρίου</span>, <strong>de vós a palavra do Senhor se propagou e ressoou</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 1.8</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀπὸ βορρᾶ, ἀπὸ νότου</span>, <strong>ao norte, ao sul</strong> (PCairGoodsp 6, 5 [129 a.C.], <span class=\"greek\">ἐν τῷ ἀπὸ νότου πεδίῳ</span>; Mitt-Wilck. I/2, 11A, col. 1, 12s. [123 a.C.], <span class=\"greek\">τὸ ἀπὸ νότου τῆς πόλεως χῶμα</span>; linha 7, <span class=\"greek\">ἀπὸ βορρᾶ τῆς πόλεως</span>; 70, 16 e outros; Js 18.5; 19.34; 1Rs 14.5): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21.13</a>.</p>\n<p class=\"entry-text\"><b>b.</b> De tempo: <strong>desde, a partir de</strong> (POxy 523, 4; Melitão, <em>HE</em> 4.26.8; Kuhring 54ss.). <b>α.</b> <span class=\"greek\">ἀπὸ τῶν ἡμερῶν Ἰωάννου</span>, <strong>desde os dias de João</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.12</a>; <span class=\"greek\">ἀπὸ τῆς ὥρας ἐκείνης</span>, <strong>desde aquela hora</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9.22</a>; <span class=\"greek\">ἀπ’ ἐκείνης τῆς ἡμέρας</span>, <strong>desde aquele dia</strong> (Josefo, <em>Bell.</em> 4.318, <em>Ant.</em> 7.382), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22.46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.53\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.53</a>; <span class=\"greek\">ἔτη ἑπτὰ ἀπὸ τῆς παρθενίας αὐτῆς</span>, <strong>sete anos desde sua virgindade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.36</a>; <span class=\"greek\">ἀπὸ ἐτῶν δώδεκα</span>, <strong>há doze anos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.43</a>; <span class=\"greek\">ἀπὸ τρίτης ὥρας τῆς νυκτός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 23.23</a>; <span class=\"greek\">ἀπὸ κτίσεως κόσμου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.20</a>; <span class=\"greek\">ἀπὸ πέρυσι</span>, <strong>desde o ano passado, há um ano</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 8.10</a>; 9.2. Veja também <span class=\"greek\">ἀπ’ αἰῶνος, ἀπ’ ἀρχῆς, ἀπ’ ἄρτι</span> (e <span class=\"greek\">ἀπαρτί, ἄρτι</span>), <span class=\"greek\">ἀπὸ καταβολῆς κόσμου, ἀπὸ τότε, ἀπὸ τοῦ νῦν</span>.</p>\n<p class=\"entry-text\"><b>β.</b> Com ambos os limites, anterior e posterior: <span class=\"greek\">ἀπὸ … ἕως</span> (Josefo, <em>Ant.</em> 6.364), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.45</a>; <span class=\"greek\">ἀπὸ … ἄχρι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1.5</a>; <span class=\"greek\">ἀπὸ … μέχρι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 10.30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5.14</a>; 15.19. <b>γ.</b> <span class=\"greek\">ἀφ’ ἧς</span>, com <span class=\"greek\">ὥρας</span> ou <span class=\"greek\">ἡμέρας</span> subentendidos (este último expresso em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.6</a>, 9; a fórmula fixou-se: ParJer 7.28; Plutarco, <em>Pelop.</em> [285] 15.5; B-D-F §241.2), <strong>desde</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.45</a> (Renehan 1975, 36s.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 24.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 3.4</a>; compare Xenofonte, <em>Hell.</em> 4.6.6; 1Mc 1.11. <span class=\"greek\">ἀφ’ οὗ</span> (subentendido <span class=\"greek\">χρόνου</span>, como Xenofonte, <em>Cyr.</em> 1.2.13; também fórmula ática em Meisterhans³-Schw.; Witkowski, índice 163), <strong>desde, desde que</strong> (Xenofonte, <em>Symp.</em> 4.62; Demétrio: 722 Fgm. 1, 16 Jac.; Luciano, <em>Dial. Mar.</em> 15.1; Êx 5.23; GrBar 3.6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13.25</a>; 24.21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16.18</a>; compare Dn 12.1; 1Mc 9.29; 16.24; 2Mc 1.7; TestAbr B 13 p. 117, 23; GrBar; Josefo, <em>Ant.</em> 4.78. <span class=\"greek\">τρία ἔτη ἀφ’ οὗ</span>, <strong>há três anos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13.7</a>; Tb 5.35 S. Para <span class=\"greek\">ἀφότε</span>, veja <span class=\"greek\">ὅτε</span> 1aγ, final.</p>\n<p class=\"entry-text\"><b>c.</b> <strong>Início de uma série; desde, a partir de.</strong> <b>α.</b> <span class=\"greek\">ἀρξάμενος ἀπὸ Μωϋσέως καὶ ἀπὸ πάντων τῶν προφητῶν</span>, <strong>começando por Moisés e todos os profetas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.27</a>. <span class=\"greek\">ἕβδομος ἀπὸ Ἀδάμ</span>, <strong>sétimo desde Adão</strong>, Jd 14; compare Diodoro Sículo 1.50.3, <span class=\"greek\">ὄγδοος ὁ ἀπὸ τοῦ πατρός</span>, <strong>oitavo a partir do ancestral</strong>; Apiano, <em>Mithrid.</em> 9 §29, sexto Mitrídates desde o primeiro; Arriano, <em>Anab.</em> 7.12.4; Diógenes Laércio 3.1, Platão como sexto na descendência de Sólon; <em>Biogr.</em> p. 31, Homero como décimo depois de Museu. <span class=\"greek\">ἀπὸ διετοῦς καὶ κατωτέρω</span>, <strong>de dois anos para baixo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2.16</a>; Nm 1.20; 2Esd 3.8. <b>β.</b> Com início e fim: <span class=\"greek\">ἀπὸ … ἕως</span> (Sir 18.26; 1Mc 9.13), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1.17</a>; 23.35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 8.10</a>; semelhantemente, <span class=\"greek\">ἀπὸ δόξης εἰς δόξαν</span>, <strong>de glória em glória</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3.18</a>.</p>\n<p class=\"entry-text\"><b>3.</b> <strong>Indica origem ou fonte; de, proveniente de.</strong> <b>a.</b> Literal, com verbos de movimento. <b>α.</b> <strong>De, para baixo a partir de</strong>: <span class=\"greek\">πίπτειν ἀπὸ τραπέζης</span>, <strong>cair da mesa</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15.27</a>; <span class=\"greek\">καθεῖλεν δυνάστας ἀπὸ θρόνων</span>, <strong>Deus depôs os poderosos de seus tronos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.52</a>. <b>β.</b> <strong>De</strong>: <span class=\"greek\">ἔρχεσθαι ἀπὸ θεοῦ</span>, <strong>vir de Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3.2</a>; 13.3; 16.30; <span class=\"greek\">παραγίνεται ἀπὸ τῆς Γαλιλαίας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3.13</a>; <span class=\"greek\">ἀπὸ ἀνατολῶν ἥξουσιν</span>, <strong>virão do Oriente</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8.11</a> (Is 49.12; 59.19); <span class=\"greek\">ἀπὸ τοῦ ἱεροῦ ἐπορεύετο</span>, <strong>retirou-se do templo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.1</a>; <span class=\"greek\">ἀπὸ Παμφυλίας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.38\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.38</a>; <span class=\"greek\">ἐγείρεσθαι ἀπὸ τῶν νεκρῶν</span>, <strong>ressuscitar dos mortos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14.2</a>.</p>\n<p class=\"entry-text\"><b>b.</b> Origem geográfica de alguém, <strong>de, oriundo de</strong> (Homero e outros; Sófocles, <em>El.</em> 701; Heródoto 8.114; inscrição <em>RevArch</em> quarta série IV [1904] p. 9, <span class=\"greek\">ἀπὸ Θεσσαλονίκης</span>; papiros em H. Braunert, <em>Binnenwanderung</em>, 1964, 384 s.v.; PFlor 14, 2; 15, 5; 17, 4; 22, 13 e outros; Jz 12.8; 13.2; 17.1 [segundo B]; 2Rs 23.20; Josefo, <em>Bell.</em> 3.422, <em>Vi.</em> 217; Justino, <em>A I</em> 1, <span class=\"greek\">τῶν ἀπὸ Φλαουΐας Νέας πόλεως</span>; B-D-F §209.3; Rob. 578).</p>\n<p class=\"entry-text\"><span class=\"greek\">ἦν ἀπὸ Βηθσαϊδά</span>, <strong>era de Betsaida</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.44\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.44</a>; 12.21; <span class=\"greek\">ὄχλοι ἀπὸ τῆς Γαλιλαίας</span>, <strong>multidões da Galileia</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4.25</a>; <span class=\"greek\">ἄνδρες ἀπὸ παντὸς ἔθνους</span>, <strong>homens de todas as nações</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.5</a>; <span class=\"greek\">ἀνὴρ ἀπὸ τοῦ ὄχλου</span>, <strong>homem da multidão</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.38</a>; <span class=\"greek\">ὁ προφήτης ὁ ἀπὸ Ναζαρέθ</span>, <strong>o profeta de Nazaré</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21.11</a>; <span class=\"greek\">οἱ ἀπὸ Κιλικίας</span>, <strong>os cilícios</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 6.9</a>; <span class=\"greek\">οἱ ἀδελφοὶ οἱ ἀπὸ Ἰόππης</span>, <strong>os irmãos de Jope</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 10.23</a>; compare Museu 153, <span class=\"greek\">παρθένος ἀπ’ Ἀρκαδίας</span>, <strong>jovem da Arcádia</strong>; Justino, <em>A I</em> 58.1, <span class=\"greek\">Μακρίωνα … τὸν ἀπὸ Πόντου</span>; <span class=\"greek\">οἱ ἀπὸ Θεσσαλονίκης Ἰουδαῖοι</span>, <strong>os judeus de Tessalônica</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 17.13</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">οἱ ἀπὸ τῆς Ἰταλίας</span>, <strong>os italianos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13.24</a>, que podem estar dentro ou fora da Itália; compare Dssm., <em>Her.</em> 33 (1898) 344; LO 167, 1 [LAE 200, 3]; Mlt. 237; B-D-F §437. Pode indicar antes <strong>associação estreita</strong>: <span class=\"greek\">οἱ ἀπὸ τῆς ἐκκλησίας</span>, <strong>membros da igreja</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 12.1</a>; 15.5; compare Plutarco, <em>Cato Min.</em> 4.2, <span class=\"greek\">οἱ ἀπὸ τῆς στοᾶς φιλόσοφοι</span>; Ps.-Demétrio c. 68, <span class=\"greek\">οἱ ἀπ’ αὐτοῦ</span>, discípulos de Isócrates; Sinésio, <em>Ep.</em> 4 p. 162b; 66 p. 206c; PTebt 33, 3 [112 a.C.], <span class=\"greek\">Ῥωμαῖος τῶν ἀπὸ συγκλήτου</span>; Arístides 15.1, <span class=\"greek\">Χριστιανοὶ γενεαλογοῦνται ἀπὸ … Ἰησοῦ Χριστοῦ</span>.</p>\n<p class=\"entry-text\">Também origem quanto ao <strong>material</strong> de que algo se faz (Heródoto 7.65; Teócrito 15.117; IPriene 117, 72, <span class=\"greek\">ἀπὸ χρυσοῦ</span>; 1Esd 8.56; Sir 43.20 v.l.): <span class=\"greek\">ἔνδυμα ἀπὸ τριχῶν καμήλου</span>, <strong>roupa feita de pelos de camelo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3.4</a>.</p>\n<p class=\"entry-text\"><b>c.</b> Figuradamente, com verbos de pedir e desejar: designa a pessoa <strong>a quem ou de quem</strong> se pede (Arístides 11.3): <span class=\"greek\">δανίσασθαι ἀπό τινος</span>, <strong>tomar emprestado de alguém</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5.42</a>; <span class=\"greek\">ἐκζητεῖν ἀπὸ τῆς γενεᾶς ταύτης</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11.51</a>; <span class=\"greek\">ἀπαιτεῖν τι ἀπό τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.20</a>; <span class=\"greek\">ζητεῖν τι ἀπό τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 2.6</a>; <span class=\"greek\">λαμβάνειν τι ἀπό τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17.25</a>s.; 3Jo 7.</p>\n<p class=\"entry-text\"><b>d.</b> Figuradamente, com verbos de percepção, marca a <strong>fonte do conhecimento</strong> (Lísias, <em>Andoc.</em> 6; Ps.-Aristóteles, <em>De Mundo</em> 6, 399b, <span class=\"greek\">ἀπ’ αὐτῶν τῶν ἔργων θεωρεῖται ὁ θεός</span>, <strong>Deus é percebido pelas próprias obras</strong>; Apiano, <em>Liby.</em> 104 §493, reconhecimento de cadáver por anel de sinete; Demétrio 722 Fgm. 2, 1, <span class=\"greek\">στοχάζεσθαι ἀπὸ τῶν ὀνομάτων</span>; Justino, <em>D.</em> 60.1; 100.2, <span class=\"greek\">ἀπὸ τῶν γραφῶν</span>). <span class=\"greek\">ἀπὸ τῶν καρπῶν αὐτῶν ἐπιγνώσεσθε αὐτούς</span>, <strong>pelos seus frutos os conhecereis</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7.16</a>, 20. <span class=\"greek\">μανθάνειν παραβολὴν ἀπὸ τῆς συκῆς</span>, <strong>aprender uma lição da figueira</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13.28</a>. <span class=\"greek\">ἀπὸ τῶν σπερμάτων μὴ ποιεῖσθαι τὴν παραβολήν</span>, <strong>não derivar nossa parábola apenas da referência às sementes</strong> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.37\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15.37</a>), AcPlCor 2.28. <span class=\"greek\">μανθάνειν τι ἀπό τινος</span>, <strong>aprender algo de alguém</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.7</a>.</p>\n<p class=\"entry-text\"><b>e.</b> <span class=\"greek\">γράψαι ἀφ’ ὧν ἠδυνήθην</span>, literalmente <strong>escrever segundo o que fui capaz</strong>, isto é, <strong>tão bem quanto pude</strong>, B 21.9; compare Taciano 12.5, <span class=\"greek\">οὐκ ἀπὸ γλώττης οὐδὲ ἀπὸ τῶν εἰκότων οὐδὲ ἀπ’ ἐννοιῶν</span> etc.</p>\n<p class=\"entry-text\"><b>4.</b> <strong>Indica distância a partir de um ponto; afastado de, a partir de</strong>. <span class=\"greek\">μακρὰν ἀπό τινος</span>, <strong>longe de alguém</strong>; <span class=\"greek\">ἀπὸ μακρόθεν</span>, <strong>de grande distância</strong>; veja <span class=\"greek\">μακράν, μακρόθεν</span>; para <span class=\"greek\">ἀπέχειν ἀπό τινος</span>, veja <span class=\"greek\">ἀπέχω</span> 4.</p>\n<p class=\"entry-text\">Com medidas precisas (correspondente ao latim <em>a</em>: B-D-F §161.1; Rob. 575; W. Schulze, <em>Graeca Latina</em>, 1901, 15ss.; Hdb. a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.18</a>; Apiano, <em>Bell. Civ.</em> 3.12 §42; CB I/2, 390, n.º 248): <span class=\"greek\">ἦν Βηθανία ἐγγὺς τῶν Ἱεροσολύμων ὡς ἀπὸ σταδίων δεκαπέντε</span>, <strong>Betânia estava perto de Jerusalém, a cerca de quinze estádios (menos de três quilômetros)</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.18</a>; <span class=\"greek\">ὡς ἀπὸ πηχῶν διακοσίων</span>, <strong>cerca de duzentos côvados (aproximadamente noventa metros)</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21.8</a>; <span class=\"greek\">ἀπὸ σταδίων χιλίων ἑξακοσίων</span>, <strong>cerca de mil e seiscentos estádios (aproximadamente 320 quilômetros)</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14.20</a>; compare Hv 4.1.5; outros exemplos em Rydbeck 68.</p>\n<p class=\"entry-text\">Hebraísmo: <span class=\"greek\">ἀπὸ προσώπου τινός</span> (Gn 16.6; Jr 4.26; Jt 2.14; Sir 21.2; 1Mc 5.34; En 103.4; Justino, <em>A I</em> 37.1, <span class=\"greek\">ἀπὸ προσώπου τοῦ πατρὸς ἐλέχθησαν διὰ Ἠσαίου … οἵδε οἱ λόγοι</span>, <strong>em nome do Pai … estas palavras foram ditas por intermédio de Isaías</strong>; 38.1 e outros), correspondente ao hebraico <span class=\"greek\" dir=\"rtl\">מִפְּנֵי</span>, <strong>da presença de alguém, para longe de alguém</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 1.9</a> (Is 2.10, 19, 21); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12.14</a> (B-D-F §§140; 217.1; Mlt-H. 466).</p>\n<p class=\"entry-text\"><b>5.</b> <strong>Indica causa, meio ou resultado.</strong> <b>a.</b> Em geral, exprime a causa: <strong>por causa de, em razão de, em consequência de</strong> (muitas referências em F. Bleek a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5.7</a>; PFay 111, 4; POxy 3314, 7, por queda de cavalo; Jt 2.20; 4[6]Esd [POxy 1010]; AscIs 3.13; Josefo, <em>Ant.</em> 9.56). <span class=\"greek\">οὐκ ἠδύνατο ἀπὸ τοῦ ὄχλου</span>, <strong>não podia por causa da multidão</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19.3</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2.4</a>, códice D; <span class=\"greek\">οὐκ ἐνέβλεπον ἀπὸ τῆς δόξης τοῦ φωτός</span>, <strong>não conseguia enxergar por causa do brilho da luz</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 22.11</a>; <span class=\"greek\">ἀπὸ τοῦ πλήθους τῶν ἰχθύων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21.6</a> (M.-É. Boismard, ad loc., veja 1f, final); <span class=\"greek\">ἀπὸ τοῦ ὕδατος</span>, <strong>por causa da água</strong>, Hs 8.2.8; <span class=\"greek\">ἀπὸ τῆς θλίψεως</span>, <strong>por causa da perseguição</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 11.19</a>; <span class=\"greek\">οὐαὶ τῷ κόσμῳ ἀπὸ τῶν σκανδάλων</span>, <strong>ai do mundo por causa dos escândalos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18.7</a> (B-D-F §176.1; Mlt. 246).</p>\n<p class=\"entry-text\"><span class=\"greek\">εἰσακουσθεὶς ἀπὸ τῆς εὐλαβείας</span>, <strong>ouvido por causa de sua piedade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5.7</a>. <strong>O texto, porém, talvez esteja corrompido; em todo caso é obscuro e recebe interpretações diversas</strong>. Além dos comentários, veja K. Romaniuk, «Die Gottesfürchtigen im NT», <em>Aegyptus</em> 44 (1964) 84; B-D-F §211; Rob. 580; verbete <span class=\"greek\">εὐλάβεια</span>.</p>\n<p class=\"entry-text\"><b>b.</b> Indica o meio: <strong>com a ajuda de, com</strong> (Heródoto e outros; Élio Aristides 37.23 K. = 2 p. 25 D.; PGM 4, 2128s., <span class=\"greek\">σφράγιζε ἀπὸ ῥύπου</span>, <strong>sela com sujeira</strong>; En 97.8). <span class=\"greek\">γεμίσαι τὴν κοιλίαν ἀπὸ τῶν κερατίων</span>, <strong>encher a barriga com alfarrobas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15.16</a> v.l. (veja <span class=\"greek\">ἐκ</span> 4aζ; Pr 18.20); <span class=\"greek\">οἱ πλουτήσαντες ἀπ’ αὐτῆς</span>, <strong>os que enriqueceram por meio dela</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18.15</a>; compare Sir 11.18.</p>\n<p class=\"entry-text\"><b>c.</b> Indica motivo ou razão: <strong>por, de, com</strong> (Apiano, <em>Bell. Civ.</em> 5.13 §52, <span class=\"greek\">ἀπ’ εὐνοίας</span>, <strong>com boa vontade</strong>; 1Mc 6.10; exemplos de papiros em Kuhring 35). <span class=\"greek\">κοιμᾶσθαι ἀπὸ τῆς λύπης</span>, <strong>dormir por causa da tristeza</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.45</a>; <span class=\"greek\">ἀπὸ τῆς χαρᾶς αὐτοῦ</span>, <strong>por causa de sua alegria</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 12.14</a>; <span class=\"greek\">ἀπὸ τοῦ φόβου κράζειν</span>, <strong>gritar de medo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14.26</a>; <span class=\"greek\">ἀπὸ φόβου καὶ προσδοκίας</span>, <strong>com medo e expectativa</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21.26</a>. Daí verbos de temor empregam <span class=\"greek\">ἀπό</span> para designar sua causa (veja 1c): <span class=\"greek\">μὴ φοβεῖσθαι ἀπὸ τῶν ἀποκτεννόντων τὸ σῶμα</span>, <strong>não temer os que matam somente o corpo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10.28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.4</a>; compare Jt 5.23; 1Mc 2.62; 3.22; 8.12; En 106.4.</p>\n<p class=\"entry-text\"><b>d.</b> Indica o <strong>agente causador</strong> de determinada ação, <strong>de</strong> (tragédias, Heródoto e outros): <span class=\"greek\">ἀπὸ σοῦ σημεῖον ἰδεῖν</span>, <strong>ver um sinal vindo de ti</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12.38</a>; <span class=\"greek\">γινώσκειν ἀπό τινος</span>, <strong>informar-se de alguém</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15.45</a>; <span class=\"greek\">ἀκούειν ἀπὸ τοῦ στόματός τινος</span>, <strong>ouvir da boca de alguém, isto é, diretamente dele</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.71\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.71</a> (Dionísio de Halicarnasso 3.8, <span class=\"greek\">ἀπὸ στόματος ἤκουσεν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 9.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 1.5</a>; <span class=\"greek\">τὴν ἀπὸ σοῦ ἐπαγγελίαν</span>, <strong>uma promessa feita por ti</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 23.21</a>; compare Atanásio 2.3, <span class=\"greek\">ταῖς ἀπὸ τῶν κατηγόρων αἰτίαις</span>, <strong>as acusações apresentadas pelos acusadores</strong>; <span class=\"greek\">ἀφ’ ἑνὸς ἐγενήθησαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11.12</a>.</p>\n<p class=\"entry-text\">É <strong>provável</strong> que <span class=\"greek\">παραλαμβάνειν ἀπὸ τοῦ κυρίου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11.23</a>, tenha o mesmo sentido: Paulo está convencido de ter sido ensinado pelo próprio Senhor. Sobre instrução direta, veja E. Bröse, «Die Präp. <span class=\"greek\">ἀπό</span> 1 Cor 11:23», <em>StKr</em> 71 (1898) 351–360; Dssm.; B. Weiss; Ltzm.; H.-D. Wendland; para comunicação <strong>indireta</strong>, Zahn e outros. <span class=\"greek\">παραλαβὼν ἀπὸ τῶν θυγατέρων Φιλίππου, ὅτι</span>, Papias 11.2, em oposição a <span class=\"greek\">παρειληφέναι ὑπὸ τῶν θυγατέρων Φιλίππου</span>, 2.9.</p>\n<p class=\"entry-text\">De causa mais remota: <span class=\"greek\">ἀπ’ ἀνθρώπων</span>, <strong>de seres humanos</strong>, em oposição à revelação transcendente, com <span class=\"greek\">δι’ ἀνθρώπου</span>; compare Artemidoro 1.73 p. 66, 11, <span class=\"greek\">ἀπὸ γυναικῶν ἢ διὰ γυναικῶν</span>; 2.36 p. 135, 26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1.1</a>. <span class=\"greek\">ἀπὸ κυρίου πνεύματος</span>, <strong>do Senhor, que é o Espírito</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3.18</a>. <span class=\"greek\">ἔχειν τι ἀπό τινος</span>, <strong>ter (recebido) algo de alguém</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 3.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 2.20</a>; 4.21.</p>\n<p class=\"entry-text\">Em fórmulas de saudação: <span class=\"greek\">εἰρήνη ἀπὸ θεοῦ πατρὸς ἡμῶν</span>, <strong>paz que procede de Deus, nosso Pai</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1.2</a>; 6.23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 1.1</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 1.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1.4</a>; Fm 3. <span class=\"greek\">σοφία ἀπὸ θεοῦ</span>, <strong>sabedoria de Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1.30</a>; <span class=\"greek\">ἔπαινος ἀπὸ θεοῦ</span>, <strong>louvor de Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4.5</a>; <span class=\"greek\">καὶ τοῦτο ἀπὸ θεοῦ</span>, <strong>e isso é produzido por Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1.28</a>.</p>\n<p class=\"entry-text\">A expressão <span class=\"greek\">εἰρήνη ἀπὸ «ὁ ὢν καὶ ὁ ἦν καὶ ὁ ἐρχόμενος»</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1.4</a>, é <strong>extraordinária</strong>. Pode representar interpretação já corrente do nome Javé, tentativa de reverenciar o nome divino mantendo-o gramaticalmente inalterado ou simplesmente outra das peculiaridades gramaticais frequentes em Apocalipse (Meyer⁶-Bousset 1906, 159ss.; Mlt. 9 n. 1; PParis 51, 33, <span class=\"greek\">ἀπὸ ἀπηλιότης</span>; Mussies 93s., 328).</p>\n<p class=\"entry-text\"><b>e.</b> Indica os <strong>agentes responsáveis</strong> por algo: <strong>de, por</strong>. <b>α.</b> O próprio sujeito: uso grego comum (Tucídides 5.60.1; Xenofonte, <em>Mem.</em> 2.10.3; Andócides, <em>Orat.</em> 2.4, <span class=\"greek\">οὗτοι οὐκ ἀφ’ αὑτῶν ταῦτα πράττουσιν</span>; Diodoro Sículo 17.56; Nm 16.28; 4Mc 11.3; En 98.4; TestAbr A 15 p. 95, 26 [Stone p. 38]; 18 p. 101, 6 [Stone p. 50]; Justino, <em>A I</em> 43.8). Fórmulas <span class=\"greek\">ἀφ’ ἑαυτοῦ</span> (plural <span class=\"greek\">ἀφ’ ἑαυτῶν</span>), <strong>por si próprio</strong>, e <span class=\"greek\">ἀπ’ ἐμαυτοῦ</span>, <strong>por mim mesmo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.57\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.57</a>; 21.30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3.5</a>; especialmente em João 5.19, 30; 8.28; 10.18; 15.4; também 7.17s.; 11.51; 14.10; 16.13; 18.34. <span class=\"greek\">ἀπ’ ἐμαυτοῦ οὐκ ἐλήλυθα</span>, <strong>não vim por mim mesmo</strong> (em contraste com envio pelo Pai), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7.28</a>; 8.42.</p>\n<p class=\"entry-text\"><b>β.</b> Agente externo. Com verbos na voz passiva ou com significado passivo, <span class=\"greek\">ἀπό</span> pode substituir <span class=\"greek\">ὑπό</span> (ocorrências isoladas no grego mais antigo, como Tucídides 1.17; Kühner-G. II/1, 457s.; frequente no grego tardio: Políbio 1.79.14; Herão I 152, 6; 388, 11; Nicolau de Damasco 90 Fgm. 130, 130 Jac.; IG XII/5, 29, 1; SIG 820, 9; PLond III, 1173, 12 p. 208; BGU 1185, 26; PFlor 150, 6, <span class=\"greek\">ἀπὸ τῶν μυῶν κατεσθιόμενα</span>; PGM 4, 256; Kuhring 36s.; 1Mc 15.17; Sir 16.4; ParJer 1.1, <span class=\"greek\">ᾐχμαλωτεύθησαν … ἀπὸ τοῦ βασιλέως</span>; Fílon, <em>Leg. All.</em> 3.62; Justino, <em>A I</em> 68.6, <span class=\"greek\">ἐπιστολὴν … γραφεῖσάν μοι ἀπὸ Σερήνου</span>; <em>D.</em> 121.3; B-D-F §210; Rob. 820; G. Hatzidakis, <em>Einl. in d. neugriech. Gramm.</em>, 1892, 211; A. Jannaris, <em>An Histor. Gk. Grammar</em>, 1897, §1507).</p>\n<p class=\"entry-text\">Precisamente aqui a tradição textual <strong>varia bastante</strong>, e a escolha da preposição provavelmente às vezes procura exprimir nuances especiais: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.29</a>b v.l. (<span class=\"greek\">ὑπό</span> no texto); 8.43b (<span class=\"greek\">ὑπό</span> variante); 10.22 códice D. <span class=\"greek\">ἀποδεδειγμένος ἀπὸ τοῦ θεοῦ</span>, <strong>atestado por Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.22</a>; <span class=\"greek\">ἐπικληθεὶς Βαρναβᾶς ἀπὸ τῶν ἀποστόλων</span> (variante <span class=\"greek\">ὑπό</span>), <strong>chamado Barnabé pelos apóstolos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">At 4.36</a>; <span class=\"greek\">κατενεχθεὶς ἀπὸ τοῦ ὕπνου</span>, <strong>vencido pelo sono</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 20.9</a>; <span class=\"greek\">ἀθετούμενος ἀπὸ τῶν παραχαρασσόντων τὰ λόγια αὐτοῦ</span>, <strong>na medida em que (Jesus) é rejeitado pelos que falsificam suas palavras</strong>, AcPlCor 2.3; <span class=\"greek\">νεκροῦ βληθέντος ἀπὸ τῶν υἱῶν Ἰσραὴλ ἐπ’ αὐτά</span>, <strong>quando um cadáver foi lançado sobre eles (os ossos de Eliseu)</strong>, AcPlCor 2.32.</p>\n<p class=\"entry-text\">Nesses exemplos, <span class=\"greek\">ἀπό</span> frequentemente designa quem <strong>origina indiretamente</strong> uma ação; pode traduzir-se <strong>às mãos de, por ordem de</strong>. <span class=\"greek\">πολλὰ παθεῖν ἀπὸ τῶν πρεσβυτέρων</span>, <strong>sofrer muito às mãos dos anciãos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.22</a>; 17.25; a ênfase é em <span class=\"greek\">παθεῖν</span> e não em <span class=\"greek\">ἀποδοκιμασθῆναι</span>. Em <span class=\"greek\">ἀπὸ θεοῦ πειράζομαι</span>, a tentação é <strong>causada por Deus, mas não executada pessoalmente por ele</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1.13</a>. <span class=\"greek\">ἡτοιμασμένος ἀπὸ τοῦ θεοῦ</span>, <strong>preparado por ordem de Deus, não pessoalmente por Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12.6</a>.</p>\n<p class=\"entry-text\"><b>6.</b> Em algumas expressões, <span class=\"greek\">ἀπό</span> <strong>substitui parcialmente um advérbio</strong>. <span class=\"greek\">ἀπὸ μέρους</span>, veja <span class=\"greek\">μέρος</span> 1c. <span class=\"greek\">ἡμέρᾳ ἀφ’ ἡμέρας</span>, <strong>dia após dia</strong>, GJs 12.3. <span class=\"greek\">ἀπὸ μιᾶς</span>, <strong>unanimemente, de modo igual, em conjunto</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14.18</a>. Segundo Wellhausen, <em>Einl.</em>² 26, seria aramaísmo derivado de <em>min ḥădāʾ</em>, <strong>de uma vez</strong> (M. Black, <em>An Aramaic Approach</em>³, 1967, 113); porém tal explicação <strong>não justifica o feminino</strong>, que também aparece em <span class=\"greek\">ἐπὶ μιᾶς</span>, Máximo de Tiro 6.3s.; En 99.9 (S. Aalen, <em>NTS</em> 13 [1967] 3), e no grego moderno <span class=\"greek\">μὲ μιᾶς</span>, <strong>de uma vez</strong> (Thumb §162 n. 2).</p>\n<p class=\"entry-text\">PSI 286, 22 emprega <span class=\"greek\">ἀπὸ μιᾶς</span> para pagamento efetuado <strong>de uma só vez</strong>; veja <em>New Docs</em> 2, 189. A expressão pode ter incluído originalmente <span class=\"greek\">γνώμης</span> (Fílon, <em>Spec. Leg.</em> 3.73), ou <span class=\"greek\">ὁρμῆς</span> (Tucídides 7.71.6), <span class=\"greek\">γλώσσης</span> (Cássio Díon 44.36.2), ou <span class=\"greek\">φωνῆς</span> (Herodiano 1.4.8); compare <span class=\"greek\">ἀπὸ μιᾶς φωνῆς</span>, Plutarco, <em>Mor.</em> 502d, sobre eco; B-D-F §241.6. Semelhantemente <span class=\"greek\">ἀπὸ τῶν καρδιῶν</span>, <strong>do coração, sinceramente</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18.35</a>. Himério, <em>Or.</em> 39 [= 5], 6, apresenta a fórmula <span class=\"greek\">διὰ μιᾶς</span>, provavelmente <strong>continuamente, sem interrupção</strong>; <em>Or.</em> 44 [= 8], 2, traz <span class=\"greek\">διὰ μιᾶς τῆς σπουδῆς</span>, <strong>com um mesmo zelo, ou com zelo bastante semelhante</strong>. — M-M.</p>\n</section></article><article id=\"entry-apobaino-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀποβαίνω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apobaínō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀποβήσομαι</span>; segundo aoristo <span class=\"greek\">ἀπέβην</span>; veja <span class=\"greek\">βαίνω</span>. Homero e outros; inscrições, papiros, LXX; TestJob 43.6.</p>\n<p class=\"entry-text\"><b>1.</b> Literalmente, <strong>descer, desembarcar, afastar-se, sair</strong>, por exemplo, de um navio para terra (Xenofonte, <em>An.</em> 5.7.9, <span class=\"greek\">ἀποβαίνειν εἰς τὴν χώραν</span>; Diógenes, <em>Ep.</em> 37.1): <span class=\"greek\">ἀποβαίνειν εἰς τὴν γῆν</span>, <strong>desembarcar em terra</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21.9</a>. Absolutamente (Tucídides 1.116.2; Josefo, <em>Bell.</em> 4.660): <span class=\"greek\">ἀποβάντες</span>, <strong>depois que desembarcaram</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.2</a>.</p>\n<p class=\"entry-text\"><b>2.</b> Figuradamente, <strong>resultar em determinado estado ou condição; ter por resultado, conduzir a</strong> (Heródoto e outros; Artemidoro 3.66; SIG 851, 9s., <span class=\"greek\">εἰ καὶ ἑτέρως τοῦτο ἀπέβη</span>; PPetr III, 42H [8] f, 5s. = Witkowski p. 15; Jó 30.31 com <span class=\"greek\">εἰς πάθος</span>; TestJob 43.6, <span class=\"greek\">εἰς κρίμα</span>; Josefo, <em>Ant.</em> 1.20; Justino, Taciano, Teófilo de Antioquia 2.11 [p. 226, 19]). <span class=\"greek\">ἀποβαίνειν εἰς μαρτύριον</span>, <strong>conduzir ao testemunho</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21.13</a>; <span class=\"greek\">ἀποβαίνειν εἰς σωτηρίαν</span>, <strong>resultar em salvação</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1.19</a> (Jó 13.16). — M-M.</p>\n</section></article><article id=\"entry-apoballo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀποβάλλω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apobállō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀποβαλῶ</span>; segundo aoristo <span class=\"greek\">ἀπέβαλον</span>; perfeito <span class=\"greek\">ἀποβέβληκα</span>. Médio: futuro terceira pessoa singular <span class=\"greek\">ἀποβαλεῖται</span>, Tb 11.8 B. Passivo: primeiro aoristo <span class=\"greek\">ἀπεβλήθην</span>; particípio perfeito <span class=\"greek\">ἀποβεβλημένος</span>. Veja <span class=\"greek\">βάλλω</span>; Homero e outros.</p>\n<p class=\"entry-text\"><b>1.</b> <strong>Remover algo preso ou que constitui uma parte estabelecida; tirar, despir, deixar cair.</strong> <b>a.</b> Literalmente, da roupa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10.50</a>. De árvore: <span class=\"greek\">ἀποβάλλειν τὰ φύλλα</span>, <strong>deixar cair as folhas</strong> (Is 1.30), Hs 3.3; <span class=\"greek\">ἀποβάλλειν</span> também <strong>derrubar, deixar cair involuntariamente</strong>, Ps.-Demétrio 65.</p>\n<p class=\"entry-text\"><b>b.</b> Figuradamente, <strong>despir-se, livrar-se</strong> (escólio a Nicandro, <em>Alexiph.</em> 450, <span class=\"greek\">τὸν ὕπνον ἀποβάλλειν</span>, <strong>sacudir o sono</strong>), de características que podem ser vestidas e tiradas como roupas (com <span class=\"greek\">ἐνδύσασθαι</span>): Hm 10.3.4; <span class=\"greek\">ἀποβάλλειν τὰς πονηρίας</span>, <strong>despojar-se das perversidades</strong>, Hs 6.1.4; <span class=\"greek\">ἀποβάλλειν πᾶσαν λύπην</span>, <strong>afastar toda tristeza</strong>, Hv 4.3.4; <span class=\"greek\">ἀποβάλλειν πονηρίαν ἀπὸ σεαυτοῦ</span>, <strong>despir-se da maldade</strong>, Hm 1.2; <span class=\"greek\">ἀποβάλλειν τὰς ἐπιθυμίας</span>, <strong>despojar-se dos desejos</strong>, Hs 9.14.1; <span class=\"greek\">τὰ ἔργα τούτων τῶν γυναικῶν</span>, <strong>as obras dessas mulheres</strong>, Hs 9.14.2. No médio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13.12</a> v.l.</p>\n<p class=\"entry-text\"><b>2.</b> <strong>Desfazer-se do que é indesejável ou inadequado; lançar fora, rejeitar.</strong> <b>a.</b> Literal: <span class=\"greek\">ἀποβάλλειν λίθους</span>, <strong>rejeitar ou lançar fora pedras</strong>, Hv 3.2.7; 3.5.5; passivo, Hv 3.7.5; Hs 9.8.4ss.; 9.9.4; 9.13.3, 6, 9; 9.30.1. <span class=\"greek\">ἀποβάλλεσθαι ἀπὸ τοῦ πύργου</span>, <strong>ser lançado da torre</strong>, Hs 9.8.3; <span class=\"greek\">ἀπὸ τοῦ οἴκου</span>, <strong>da casa</strong>, Hs 9.13.9; <span class=\"greek\">ἐκ τῆς οἰκοδομῆς</span>, <strong>da construção</strong>, Hs 9.7.1; 9.9.5. Com destino: <span class=\"greek\">ἀποβάλλεσθαι εἰς τὸν ἴδιον τόπον</span>, <strong>ser recolocado no próprio lugar</strong>, Hs 9.12.4; <span class=\"greek\">ἀποβάλλεσθαι πρὸς τοὺς λοιπούς</span>, <strong>ser lançado fora com os demais</strong>, Hs 9.8.7.</p>\n<p class=\"entry-text\"><b>b.</b> Figuradamente, <strong>rejeitar alguém</strong>, com acusativo pessoal (Teócrito 11.19; Hipócrates, <em>Ep.</em> 10.4), 2Cl 4.5; passivo, 1Cl 45.3; Hs 9.18.3s.; 9.22.3. <span class=\"greek\">ἐσκανδαλισμένους ἀπὸ τῆς πίστεως ἀποβάλλειν</span>, <strong>rejeitar aqueles que foram desviados da fé</strong> (ordem negativa: não rejeitar), Hm 8.10; compare escólio a Nicandro, <em>Ther.</em> 270, <span class=\"greek\">ἀποβαλλομένη τῆς εὐθείας ὁδοῦ</span>, <strong>desviada do caminho correto</strong>.</p>\n<p class=\"entry-text\"><b>3.</b> <strong>Ficar sem algo; perder</strong>, com objeto no acusativo (Heródoto e outros; Epicteto 2.10.15, <span class=\"greek\">ἀποβάλλειν αἰδῶ</span>; Díon Crisóstomo 17[34].39, <span class=\"greek\">ἀποβάλλειν τὴν παρρησίαν</span>; Dt 26.5; Fílon, <em>Abr.</em> 235, 236; <em>Spec. Leg.</em> 3.202; Josefo, <em>Bell.</em> 1.90, <em>Ant.</em> 8.225; 14.77; Arístides 13.5). <span class=\"greek\">τὴν παρρησίαν</span>, <strong>a confiança</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.35\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10.35</a>; porém <strong>lançar fora</strong> (Luciano, <em>Dial. Mort.</em> 10.1; Eliano, <em>VH</em> 10.13 etc.) também é provável. Do ouro: <span class=\"greek\">ἀποβάλλει τὴν σκωρίαν</span>, <strong>perde sua escória</strong>, Hv 4.3.4; <span class=\"greek\">ἐὰν μὴ … ἀποβάλῃ ἐξ αὐτοῦ τι</span>, <strong>a menos que perca alguma parte de si</strong>, Hv 3.6.6.</p>\n<p class=\"entry-text\"><b>4.</b> <strong>Remover de um posto oficial; destituir, depor</strong>, com pessoa e ofício: <span class=\"greek\">ἀποβάλλειν τῆς ἐπισκοπῆς</span>, <strong>depor do ofício de supervisão</strong>, 1Cl 44.4 (Ltzm., <em>ZWT</em> 55 [1913] 135); no passivo <span class=\"greek\">ἀποβάλλεσθαι τῆς λειτουργίας</span>, <strong>ser afastado do próprio ofício</strong>, 1Cl 44.3. — M-M.</p>\n</section></article><article id=\"entry-apoblepo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀποβλέπω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apoblépō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Imperfeito <span class=\"greek\">ἀπέβλεπον</span>; primeiro aoristo <span class=\"greek\">ἀπέβλεψα</span>; tragédias gregas, Heródoto e outros.</p>\n<p class=\"entry-text\"><strong>Olhar, prestar atenção</strong>, com <span class=\"greek\">εἴς τι</span> para o objeto (Epicteto 1.6.37; SIG 867, 10; PSI 414, 9; Sl 9.29; 10.4; Fílon, <em>Spec. Leg.</em> 1.293; Justino, <em>D.</em> 112.1; Melitão); com <span class=\"greek\">πρός</span> em Justino, <em>A I</em> 18.1; Taciano 21.2; Atanásio, <em>R.</em> 67.23. Figuradamente, acerca de Moisés: <span class=\"greek\">ἀποβλέπων εἰς τὴν μισθαποδοσίαν</span>, <strong>tendo em vista a recompensa</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11.26</a> (Josefo, <em>Bell.</em> 2.311, <em>Ant.</em> 20.61). — M-M; Spicq.</p>\n</section></article><article id=\"entry-apobletos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπόβλητος</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apóblētos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><span class=\"greek\">ἀπόβλητος, ον</span>, adjetivo verbal de <span class=\"greek\">ἀποβάλλω</span>; Homero e outros; papiros; Áquila, Símaco; Fílon, <em>Spec. Leg.</em> 2.169 (Nägeli 25).</p>\n<p class=\"entry-text\"><strong>Rejeitado</strong> (Herm. Wr. 6.1); daí <strong>impuro</strong>, em oposição a <span class=\"greek\">καλός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 4.4</a>. — DELG s.v. <span class=\"greek\">βάλλω</span>.</p>\n</section></article><article id=\"entry-apobole-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀποβολή</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apobolḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><span class=\"greek\">ἀποβολή, ῆς, ἡ</span>; veja <span class=\"greek\">ἀποβάλλω</span>. Platão e outros; PLond 1659, 10. Corresponde aos diversos sentidos do verbo de origem.</p>\n<p class=\"entry-text\"><b>1.</b> <strong>Rejeição</strong>: rejeição <strong>temporária</strong> dos israelitas por Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11.15</a>, em oposição a <span class=\"greek\">πρόσλημψις</span>; compare Josefo, <em>Ant.</em> 4.314, onde não se refere à rejeição do próprio povo, mas à repetida perda de cidades e do templo pela providência divina.</p>\n<p class=\"entry-text\"><b>2.</b> <strong>Perda</strong> (PCairZen 569, 25, 106 [século III a.C.]; carta 55 de Apolônio de Tiana [Filóstrato I 358, 19], perda por morte; Fílon, <em>Praem.</em> 33, de navio; Josefo, <em>Ant.</em> 2.147; Taciano 15.4; Sexto 257): <span class=\"greek\">ἀποβολὴ ψυχῆς οὐδεμία ἔσται ἐξ ὑμῶν</span>, <strong>nenhum de vós perderá a vida</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 27.22</a>; compare Estráton de Lâmpsaco, Fgm. 124, <span class=\"greek\">ἀποβολὴ ζωῆς</span>. — DELG s.v. <span class=\"greek\">βάλλω</span>.</p>\n</section></article><article id=\"entry-apoginomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπογίνομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apogínomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Segundo aoristo <span class=\"greek\">ἀπεγενόμην</span>; em nossa literatura, oposto de <span class=\"greek\">ζῆν</span>, <strong>viver</strong>. <strong>Morrer, falecer</strong> (Heródoto; Tucídides, <em>Hist.</em> 1.39.3, <span class=\"greek\">τῶν ἁμαρτημάτων ἀπογενόμενοι</span>, no sentido de <strong>não ter participação nos erros</strong>; Teles 59, 11s.; Dionísio de Halicarnasso 4.15; SIG 1099, 15; SIG² 850, 12; papiros, PMagd 29, 3; PRyl 65, 9; PGrenf II, 69, 10; PLips 29, 9, 10, 13; veja Preis.; PGM 4, 719; Josefo, <em>Ant.</em> 5.1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2.24</a>; Ox 1081, 12, 16 (= SJCh 89, 14), <span class=\"greek\">[οὐκ ἀπο]γείν[εται]</span>. — <em>New Docs</em> 3, 62; DELG s.v. <span class=\"greek\">γίγνομαι</span>; M-M; TW.</p>\n</section></article><article id=\"entry-apoginosko-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπογινώσκω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apoginṓskō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Segundo aoristo, terceira pessoa singular <span class=\"greek\">ἀπέγνω</span>, Dt 33.9; perfeito <span class=\"greek\">ἀπέγνωκα</span>; particípio perfeito passivo <span class=\"greek\">ἀπεγνωσμένος</span> (Jt 9.11).</p>\n<p class=\"entry-text\"><strong>Abandonar algo como irremediável; desesperar, perder a esperança</strong> (Lísias e outros; SIG 326, 30; PCairZen 298, 4; 2Mc 9.22; Jt 9.11; Atanásio, <em>R.</em> 68.2 e outros). Com acusativo da coisa (Aristóteles, <em>EN</em> 1115b, 2 e outros; UPZ 144, 10 [século II a.C.]; PGiss 72, 12s., <span class=\"greek\">τοῦτο ἀπέγνων</span>; Josefo, <em>Ant.</em> 2.140, <span class=\"greek\">τὴν σωτηρίαν</span>, 2.336 etc.): <span class=\"greek\">ἀπογινώσκειν ἑαυτόν</span>, <strong>desesperar de si mesmo</strong> (Políbio 22.9.14; Plutarco, <em>Tib. Gracch.</em> 830 [13]; Fílon, <em>Somn.</em> 1.60; Josefo, <em>Bell.</em> 5.537), Hv 1.1.9; Hs 9.26.4; <span class=\"greek\">τὴν ζωήν</span>, <strong>da vida</strong>, Hm 12.6.2 (compare Fílon, <em>Leg. ad Gai.</em> 352, <span class=\"greek\">τὸ ζῆν ἀπογινώσκειν</span>).</p>\n<p class=\"entry-text\"><span class=\"greek\">ὁ τὰ ἀπεγν̣ω̣[σμένα …] ἐπιστρ[έφ]ων εἰς σέ</span>, <strong>tu, que voltas para ti (Jesus) [corações] desesperados</strong>, Ox 850 (AcJ), linhas 6s.</p>\n</section></article><article id=\"entry-apognorizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπογνωρίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apognōrízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><strong>Desapossar, rejeitar</strong>; no passivo <span class=\"greek\">ἀπογνωρίζεσθαι ἀπὸ τῆς ζωῆς</span>, <strong>ser privado da própria vida</strong>, Hv 2.2.8. Em jogo de palavras com <span class=\"greek\">ἀρνέομαι</span>, <strong>negar — desmentir</strong>. — DELG s.v. <span class=\"greek\">γιγνώσκω</span>.</p>\n</section></article><article id=\"entry-apographe-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπογραφή</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apographḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><span class=\"greek\">ἀπογραφή, ῆς, ἡ</span>; veja <span class=\"greek\">ἀπογράφω</span>. Lísias, Platão e outros; SIG 1023, 45 e 71; 1109, 34; 1157, 33; OGI 338, 11 e 34; muito frequente nos papiros; LXX, EpArist, Josefo; Justino, <em>A I</em> 34.2 e <em>D.</em> 78.4.</p>\n<p class=\"entry-text\">Termo administrativo, <strong>lista, inventário</strong>, relativo aos relatórios estatísticos e declarações dos cidadãos destinados à elaboração de listas tributárias e registros familiares (Mitt-Wilck. I/1, 175s., 178, 202ss., 225ss.; I/2, 198ss., especialmente 202: édito de recenseamento de C. Víbio Máximo, de 104 d.C. [= PLond III, 904, 25s., restaurado]; Dssm., LO 231s. [LAE 268s.]).</p>\n<p class=\"entry-text\">Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.2</a>, <strong>recenseamento, registro</strong>, especificamente o recenseamento realizado por Quirínio. Josefo situa um recenseamento de Quirínio em 6/7 d.C. (compare <em>Bell.</em> 7.253; <em>Ant.</em> 18.3). Presumivelmente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">At 5.37</a>, <span class=\"greek\">ἐν ταῖς ἡμέραις τῆς ἀπογραφῆς</span>, <strong>nos dias do recenseamento</strong>, também se refere a esse censo.</p>\n<p class=\"entry-text\"><strong>A cronologia apresenta numerosos problemas</strong>, discutidos nas obras de referência. Veja Schürer I 399–427 (bibliografia); Ramsay, <em>Bearing</em> 238ss.; Zahn, <em>Lk</em> 129–135 e Excurso IV; E. Klostermann, manual sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.1</a>–3; M.-J. Lagrange, <em>RB</em> nova série 8 (1911) 60–84; E. Groag, <em>Prosopogr. Beitr.</em> VII (<em>JÖAI</em> 21/22, 1924, suplemento, colunas 445–478); H. Windisch, <em>NThT</em> 16 (1927) 106–124; A. von Premerstein, <em>Ztschr. d. Savigny-Stiftg. f. Rechtsgeschichte</em> 48 (1928), seção romana, 449ss.; L. R. Taylor, <em>AJP</em> 54 (1933) 120–133; R. Syme, <em>The Roman Revolution</em>, 1939, 397–401; E. Seraphin, <em>CBQ</em> 7 (1945) 91–96; F. Hauck, <em>Theol. Hndkomm.</em>, <em>Lk</em> p. 37; Goodspeed, <em>Probs.</em> 71s.</p>\n<p class=\"entry-text\">Ainda: M. Hombert e C. Préaux, <em>Recherches sur le recensement dans l’Egypte romaine</em>, 1952; E. Stauffer, <em>Jesus, Gestalt u. Geschichte</em>, 1957; «Die Dauer des Census Augusti», <em>Studien zum NT u. zur Patristik</em> (1961) 9–34; H. Instinsky, <em>Das Jahr der Geburt Christi</em>, 1957; H. Braunert, <em>Historia</em> 6 (1957) 192–214; «Cives Romani und <span class=\"greek\">ΚΑΤ’ ΟΙΚΙΑΝ ΑΠΟΓΡΑΦΑΙ</span>», em <em>Antidoron M. David</em>, <em>Papyrologica Lugduno-Batava</em> 17 (1968) 11–21; E. Stauffer, <em>Festschrift Klostermann</em> (1961) 9ss.; J. Thorley, «The Nativity Census: What Does Luke Actually Say?», <em>Greece and Rome</em>, segunda série 26 (1979) 81–84; Haenchen, ad loc.; B. Palme, <em>ProBib</em> 2 (1993) 1–24. Veja também <span class=\"greek\">ἡγεμονεύω</span> e <span class=\"greek\">Κυρήνιος</span>. — Boffo, <em>Iscrizioni</em> 182s. (bibliografia); <em>New Docs</em> 6, 115–119; DELG s.v. <span class=\"greek\">γράφω</span>; M-M.</p>\n</section></article><article id=\"entry-apographo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπογράφω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apográphō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Médio: futuro <span class=\"greek\">ἀπογράψομαι</span>; primeiro aoristo <span class=\"greek\">ἀπεγραψάμην</span>. Passivo: segundo aoristo <span class=\"greek\">ἀπεγράφην</span>, LXX; particípio perfeito <span class=\"greek\">ἀπογεγραμμένος</span>. Heródoto e outros; inscrições, papiros, LXX, En; TestSol 28.8 B; TestAbr.</p>\n<p class=\"entry-text\">Literalmente, <strong>retirar uma cópia por escrito, copiar</strong>, termo comum da preparação de cópias de documentos oficiais. Daí <strong>inserir numa lista, registrar</strong>.</p>\n<p class=\"entry-text\"><b>a.</b> <strong>Registro oficial em listas tributárias</strong> (Philol 71 [1912] 24; POxy 249, 5; 250, 1; PLond III, 904, 32 [século I d.C.] p. 126, entre outros; compare <span class=\"greek\">ἀπογραφή</span>). No médio, como termo técnico, <strong>registrar-se, recensear-se</strong> (Arriano, <em>Anab.</em> 3.19.6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.3</a>, 5; no passivo, v. 1. Com José como objeto: <span class=\"greek\">ἀπογράψομαι τοὺς υἱούς μου</span>, <strong>farei registrar meus filhos</strong>, GJs 17.1, seguido de <span class=\"greek\">πῶς αὐτὴν (Μαρίαν) ἀπογράψομαι;</span>, <strong>como farei registrar a ela (Maria)?</strong> Provavelmente nesse mesmo sentido <span class=\"greek\">ἀπογράψασθαι ὅσοι εἰσὶν ἐν Βηθλεέμ</span>, no mesmo texto. Para <strong>declarar bens</strong>, PTaur LVII, 11 [século II a.C.]; compare POxy 246, 10 [século I d.C.] e referências adicionais em DGE s.v.</p>\n<p class=\"entry-text\"><b>b.</b> Figuradamente, <strong>registros mantidos por Deus</strong> — o Livro da Vida (compare En 98.7s.; TestAbr A 12 p. 91, 11 [Stone p. 30]; ApcPl 10 p. 39s. Tdf.: <span class=\"greek\">πάντα τὰ πραττόμενα παρ’ ὑμῶν καθ’ ἡμέραν ἄγγελοι ἀπογράφονται ἐν οὐρανοῖς</span>, <strong>todos os atos que praticamos diariamente são registrados pelos anjos no céu</strong>): <span class=\"greek\">πρωτότοκοι ἀπογεγραμμένοι ἐν οὐρανοῖς</span>, <strong>primogênitos registrados nos céus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12.23</a>. Veja <span class=\"greek\">ἀπογραφή</span>. — EDNT; M-M s.v. <span class=\"greek\">ἀπογράφομαι</span>; <em>New Docs</em> 1, 79s., com exemplos de declaração típica (BGU 2223) e extrato de registro (BGU 2228), ambos do século II d.C.</p>\n</section></article><article id=\"entry-apodeiknumi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀποδείκνυμι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apodeíknumi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἀπέδειξα</span>; passivo: primeiro aoristo <span class=\"greek\">ἀπεδείχθην</span> (LXX), perfeito da terceira pessoa singular <span class=\"greek\">ἀποδέδεικται</span> (Ar 13.8; Justino), particípio <span class=\"greek\">ἀποδεδειγμένος</span> (Píndaro, Heródoto e outros). Em geral, «apontar para fora» e «dirigir a atenção» para um objeto específico.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Exibir para reconhecimento público como alguém ou alguma coisa, constituir, fazer, apresentar, proclamar, designar.</strong> Especialmente termo administrativo com duplo acusativo e vários valores: Xenofonte, <em>Cyr.</em> 1.2.5 (<span class=\"greek\">παῖδας βελτίστους ἀ.</span>); <em>Socratics</em>, Ep. 28.11 (= Malherbe 292, 10); Diodoro Sículo 2.26.6; Arriano, <em>Anab.</em> 6.2.1; Dn 2.48; 2Mc 14.26 (Swete); Josefo, <em>Ant.</em> 8.162; Justino, <em>D.</em> 86.4 (<span class=\"greek\">ῥάβδος … ἀρχιερέα αὐτὸν ἀπέδειξε</span>, «a vara [de Arão] o declarou sumo sacerdote»). A respeito de Deus: Josefo, <em>Ant.</em> 11.3; TestJos 2.7. <span class=\"greek\">ἡμᾶς τοὺς ἀποστόλους ἐσχάτους ἀπέδειξεν</span>, <strong>ele nos apresentou, os apóstolos, como os últimos</strong>, talvez numa procissão triunfal, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4.9</a>; a ironia de Paulo sugere duplo sentido. Com <span class=\"greek\">ὅτι</span> em lugar do segundo acusativo: <span class=\"greek\">ἀποδεικνύντα ἑαυτὸν ὅτι ἔστιν θεός</span>, <strong>proclamando que ele próprio é Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2.4</a>. Passivo: <span class=\"greek\">διάκονοι, ἀποδεδειγμένοι ἐν γνώμῃ Ἰησοῦ</span>, <strong>auxiliares designados com a aprovação de Jesus</strong>, IPhld, inscrição; compare PPetr III 36a verso, 17 (<span class=\"greek\">ἀποδεδειγμένοι ἐπίσκοποι</span>); PGen 36.2; Josefo, <em>Ant.</em> 7.356.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Manifestar a qualidade de algo, mostrar, exibir.</strong> PLond III 904, 34 (104 d.C.), p. 126; BGU 388 II, 19. <span class=\"greek\">τὸ ἀκέραιον τῆς πραΰτητος αὐτῶν βούλημα ἀποδειξάτωσαν</span>, <strong>que manifestem disposição sincera e mansa</strong>, 1Cl 21.7. No passivo: <span class=\"greek\">ἄνδρα ἀποδεδειγμένον ἀπὸ τοῦ θεοῦ</span>, <strong>homem atestado por Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.22</a>; compare Est 3.13c e Diodoro Sículo 20.40.6 (<span class=\"greek\">ἀποδεδειγμένος εἰς τ. πόλιν</span>, «bem-quisto na cidade»).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Demonstrar que algo é verdadeiro, provar</strong>, com acusativo da coisa: 4Mc 1.8; TestAbr B 115.17s. (Stone p. 78); Justino, <em>A I</em> 52.1 (acusativo com infinitivo), <em>D.</em> 100.1; 68.1 (<span class=\"greek\">ὅτι</span>); 59.1 (<span class=\"greek\">πῶς</span>) e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 25.7</a>. — E. Peterson, <em>Deissmann Festschrift</em>, 1926, 320ss.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">4.</span> Como <span class=\"greek\">δείκνυμι</span>, <strong>dirigir a atenção a objeto específico, mostrar</strong> (Heródoto 3.122.4; Tucídides 1.129.1): <span class=\"greek\">προῆγεν αὐτ[οὺς …] |.[. φ]ωσ̣[τὴ]ρ ἀπεδίκνυεν</span>, <strong>(Cristo) ia à frente deles e, [como] uma estrela, lhes mostrava o caminho</strong>, AcPl Ha 7, 34s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10.1</a>, variante do códice D. — M-M.</p>\n</section></article><article id=\"entry-apodeixis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπόδειξις</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apódeixis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><span class=\"greek\">ἀπόδειξις, εως, ἡ</span>; veja <span class=\"greek\">ἀποδείκνυμι</span>; pré-socráticos, Heródoto e outros. Literalmente, <strong>ato de apontar algo com finalidade demonstrativa; demonstração, prova</strong>, especialmente de uma intervenção divina ou a favor dela (Diodoro Sículo 15.49.4; Teófilo de Antioquia 1.13 [p. 86, 26]).</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀπόδειξις πνεύματος καὶ δυνάμεως</span>, literalmente <strong>demonstração de espírito e poder</strong>, isto é, demonstração que consiste na posse do Espírito Santo e do poder de realizar milagres, em contraste com <span class=\"greek\">πειθοὶ λόγοι</span>, «palavras persuasivas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 2.4</a>. Compare Fílon, <em>Mos.</em> 1.95 (<span class=\"greek\">ἀπόδειξις διὰ σημείων καὶ τεράτων</span> em oposição a <span class=\"greek\">διὰ τῶν λόγων</span>). Sobre sua relação com a retórica antiga, veja G. Dautzenberg, <em>EDNT</em> I 127; H. Hommel/K. Ziegler, <em>Pauly-W.</em> IV 1396–1414. — M-M; TW; Sv.</p>\n</section></article>"};
